      "summary": "8/12(水)の東京市場は日経平均が前営業日(8/10)比553円84銭高(+0.83%)の6万7,524円06銭と続伸した。始値6万6,994円05銭、安値6万6,735円76銭(09:01)、高値6万7,569円36銭(14:33)とほぼ高値引けで、前場は6万7,000円台を挟んだ狭いレンジだったが後場に押し目買いが優勢になった。TOPIXは4,139.00(+38.39/+0.94%)と7月6日の過去最高値4,101.96を上抜けて史上最高値を更新し、日経平均を上回る上昇率が示すとおり8/10の値がさ半導体一辺倒から幅広い銘柄への物色に広がった。プライム売買代金は概算9兆4,421億円、値上がり983(63.1%)・値下がり530・変わらず43。業種別では非鉄金属+3.12%、銀行業+2.87%、鉱業+2.77%が上位で、原油高(WTI 83.20ドル)と長期金利の高止まりが資源・金融株を押し上げた。個別では米ファンドの16%超保有が判明した太陽誘電が売買代金2,942億円を伴って+7.51%、キオクシアHDが+3.87%・売買代金1兆9,253億円、フジクラが+3.94%の高値引けと、AI・半導体まわりの資金は途切れていない。半面、決算を跨いだ銘柄の選別は厳しく、サンリオ-18.12%、楽天グループ-13.77%(安値引け)、メック-14.37%(一時ストップ安)と、好業績でも市場予想比で下振れた銘柄は容赦なく売られた。ストップ高12銘柄・ストップ安4銘柄。",
