          "scenario": "8/12の15:30に上期決算と通期予想を開示した。26年12月期上期(1-6月)の連結経常利益は前年同期比2.2倍の162億円で、従来予想127億円を28.0%上回って着地している。これまで非開示だった通期予想を新たに提示し、経常320億円(前期比87.1%増)、営業利益314億円(同89.8%増)、売上高1,038億円(同47.9%増)と3期連続最高益の見通しとした。未定としていた期末一括配当も178円(前期95円)に設定している。生成AI関連のメモリ半導体向けプローブカードの増産が牽引しており、4-6月期単体の売上営業利益率は24.8%から35.1%へ急上昇した。当日の株価は決算前に13,950円(+0.43%)とほぼ横ばいで引けており、材料は株価に入っていない。夜間PTSは14,610円(+4.73%)。ギャップが一桁%にとどまる点は、本日ギャップ+14.94%で寄って寄り天になったスクウェア・エニックスHDと対照的で、8/7のテルモ(PTS+4.09%→寄り+5.35%→大引け+3.02%)に近い型を想定している。当日売買代金240.1億円は今回のプラン中で最も厚く、寄りで値がつかないリスクは小さい。【8/13 7:00 朝更新】夜間PTSは23:57時点で14,880円(終値比+6.67%)と夕方の14,610円(+4.73%)からさらに上昇した。米国では8/12にSOX指数が+2.49%と大幅高になり、同社と工程が近いアプライド・マテリアルズが+4.29%、マイクロンが+4.92%と半導体は全面高で、テーマの追い風は夕方時点より明確に強まっている。株探も8/13 7:01配信の「本日注目すべき【好決算】銘柄」で同社を筆頭に取り上げており、朝の注目度は高い。一方で日経225先物が現物比1,000円超の上サヤにあるため、指数の押し上げぶんが個別のギャップに上乗せされる点は割り引いて見たい。",
          "entry": "朝のPTS水準どおりなら+6〜7%前後のギャップアップになる。指数自体が1.5%飛んで寄る想定のため、そのぶんを差し引いた個別の強さが出ているかを見たい。寄り成りで飛びつく形は取らず、寄り付き後に寄り値を割らずに高値を切り上げるか、前場の押し目で寄り値近辺を維持する形を確認してからが目安。8/12夜の米CPIを通過した後の寄り付きになるため、指数が素直に上を向いているかを先に確認したい。",
          "invalidation": "寄り値を明確に割り込んで前日終値13,950円方向へ戻し始めたら、通期予想の初開示が寄り付きで消化された形としてシナリオは無効。キオクシアHD・フジクラなど半導体・AI主力が同時に売られる展開になった場合も前提が崩れる。",
          "risk": "SNS上では7-9月期が大幅減速するとの見方も出ており(@SHINNISA202401)、通期320億円から上期162億円を差し引いた下期158億円は上期とほぼ同水準にとどまる計算のため、上期の勢いがそのまま続く前提の買いは危うい。信用倍率13.82倍と需給面の重さを指摘する投稿もある。【8/13 7:00 朝更新】米CPI上振れによる急落リスクは、4項目すべて予想通りの着地で解消した。代わって意識すべきは寄り天リスクで、米国では引け後のシスコが通期見通し大幅上振れでも利益率を嫌気され時間外-4.09%と売られている。指数が1,000円超のギャップアップで寄る日は、好材料が寄り付きで一気に消化されて以降は戻り待ちの売りに押される形が出やすい。8/13は引け後に米アプライド・マテリアルズの決算を控えており、半導体装置・テスト関連は結果待ちで上値を追いにくい時間帯が生じる可能性もある。株価が1万円超の値がさで1単元あたりの必要資金が大きく、値動きも荒くなりやすい。",
