          "scenario": "8/12の15:30に1Q決算を開示した。27年3月期1Q(4-6月)の連結経常利益は前年同期比53.1%増の229億円で、通期計画835億円に対する進捗率は27.5%と5年平均の20.0%を上回っている。売上高は4,573億円(前年同期比15.0%増)、営業利益200億円(同47.9%増)で、前期に買収した米州の軟包装事業の寄与とアジア需要が効いた生活・産業事業が牽引した。売上営業利益率も3.4%から4.4%へ改善している。ただし通期計画の増額修正は現時点で発表されていない。当日の終値は4,918円(+2.12%)で、夜間PTSは5,260円(+6.96%)。本日TOPIXが史上最高値を更新し、8/10の値がさハイテク偏重から非鉄・銀行を含む幅広い銘柄へ物色が広がっている流れは、この規模の内需系大型株にとって追い風になる。時価総額と板の厚さは今回のプラン中で最上位クラスで、寄り付きで値がつかないリスクはほぼない。【8/13 7:00 朝更新】夜間PTSは23:57時点で5,470円(終値比+11.22%)まで買われ、PTS夜間値上がり率12位に入った。夕方の+6.96%から二桁%へ膨らんだことで、このプランを2位に置いた根拠の一つだった「ギャップが一桁%にとどまるので寄り天になりにくい」という前提は崩れている。日経225先物も現物比1,000円超の上サヤで、指数の押し上げぶんがさらに上乗せされる形になる。決算の中身(1Q経常53%増・進捗率27.5%)は変わらないが、寄り付きでどこまで織り込まれるかの読みが難しくなったためスコアを61から58へ引き下げた。株探の8/13 7:01配信「本日注目すべき【好決算】銘柄」には同社も掲載されている。決算の内訳も判明しており、生活・産業事業のパッケージ・建装材が海外販売好調で牽引、エレクトロニクス事業はテクセンドフォトマスクの持分法適用会社移行で大幅減収ながら高密度半導体パッケージ基板(FC-BGA)の伸長で増益を確保した形。",
