          "risk": "会社側は通期計画835億円を据え置いており、上方修正が出たわけではない点で材料の強さは一段落ちる。進捗率27.5%は5年平均を上回るとはいえ絶対値としては通期の3割弱で、下期の不透明感を打ち消すほどではない。8/12の東京市場ではサンリオが営業益過去最高でも市場予想比の下振れで-18.12%、メックが2度目の上方修正でも織り込み済みとして-14.37%まで売られており、決算の絶対値ではなく市場予想との比較で判断される地合いが続いている。【8/13 7:00 朝更新】米CPIによる指数急落リスクは解消した一方、PTSが+11%まで膨らんだことで「大型株のぶんギャップの剥落も緩やか」という当初の想定は当てにしにくくなった。時価総額の大きい銘柄が二桁%のギャップアップで寄った場合、買い遅れた資金が入るより先に、決算を跨いで持っていた側の利益確定が出やすい。米国でもシスコが好決算・見通し上振れでありながら利益率を嫌気されて時間外-4.09%と売られており、寄り高後の失速は警戒しておきたい。",
