          "basis": "IR(8/12の取引終了後に海外向け公募増資1,500万株を発表、手取り概算482億円、発行済株式総数が約10.5%増加する希薄化、発行価格は8/12〜13のいずれかの日に決定) × PTS 3,512.2円(17:53時点、当日終値3,661円比-4.07%) × 当日売買代金40.5億円で売りプランとして十分な流動性 × 希薄化は決算のような解釈の幅がなく方向が読みやすいイベント",
          "scenario": "8/12の取引終了後に、新株1,500万株の海外向け公募発行を発表した。手取り概算482億円は国内外の設備投資資金とM&A待機資金に充当する方針で、発行価格は8月12〜13日のいずれかの日に決定される。発行済株式総数が約10.5%増える希薄化がネガティブ視されており、夜間PTSは3,512.2円(-4.07%)。当日の株価は3,661円(-0.35%)とほぼ横ばいで、増資は完全に材料未消化の状態にある。公募増資は決算のように内容の解釈で評価が分かれる材料ではなく、希薄化率という数字がそのまま需給の重しになる点で方向が読みやすい。加えて発行価格の決定日が8/13にかかる可能性があり、値決めを意識した売りが日中に出やすい構図でもある。当日売買代金40.5億円は売りプランとして十分な厚みがある。【8/13 7:00 朝更新・重要】8/12 23:00にTDnetで「海外募集による新株式の発行条件等の決定に関するお知らせ」が開示され、発行条件が確定した。発行価格は1株3,349円、ディスカウント率8.52%(算定基準日8/12・基準価格3,661円)、発行価格総額502億3,500万円、払込金額は1株3,202.56円。発行済株式総数は142,325,934株から157,325,934株へ増える。手取概算477億円の使途は長岡工場の設備投資150億円、ポーランド工場の鋳物内製化140億円、シカゴのR&D・ソリューションセンタ60億円、キーコンポーネント内製化27億円、M&A待機資金100億円と具体的に示された。この開示により、夕方に挙げた根拠のうち「発行価格の決定日が8/13にかかる可能性があり値決めを意識した売りが日中に出やすい」という前提は消えている。さらに指数が現物比1,000円超のギャップアップで寄る地合いは売り方向には逆風で、工作機械は設備投資テーマとして買われる側にも回りうる。この2点を踏まえスコアを54から47へ引き下げた。なお発行価格3,349円は夜間PTSの3,480円より下にあり、需給上の下値メドとして意識されうる水準になる。",
          "entry": "-5%前後のギャップダウンが前提のため寄り成りの売りは取らない形が基本。寄り付き後に一度戻りを入れて寄り値を上抜けられずに失速する形を確認してからの戻り売りが目安。本日のサンリオのように寄り後も下値を切り下げ続ける形になれば、寄り値割れが継続の目安になる。",
          "invalidation": "寄り値を明確に上抜けて上昇に転じた場合は、482億円の使途(設備投資・M&A)が前向きに評価された形として売りシナリオは無効。【8/13 7:00 朝更新】発行価格は8/12 23:00の開示で3,349円に確定済みのため、値決め絡みの売り圧力という前提は既に消えている。加えて発行価格3,349円まで下げた水準では、増資を引き受ける側との価格差がなくなり下値が固くなる可能性があるため、そこから先を追う形は取らない。",
          "risk": "売り方向は8/5以降「寄り付きで売れない・売っても日中に戻される」形が繰り返し出ており、本日のサンリオでようやく4営業日ぶりに機能したばかりで、勝ちパターンが定着したとは言えない。増資による希薄化は事前にある程度織り込まれている場合があり、-4%程度のギャップで消化が終わる可能性もある。工作機械は本日の東京市場で買われた資源・設備投資関連のテーマに含まれ、地合いが強ければ増資を吸収して切り返す展開もありうる。PTSの出来高は確認できておらず、-4.94%という気配の信頼度は高くない。【8/13 7:00 朝更新】米CPIが波乱なく通過して日経225先物が現物比1,000円超の上サヤになったことは、この売りプランにとって最も大きな逆風である。指数が1.5%上昇して寄る日は、希薄化の織り込みが薄い水準で下げ止まって切り返す形が起こりやすい。加えて発行価格が3,349円に確定したことで下値のメドが明示された点も、下げ幅を限定する方向に働きうる。",
