          "scenario": "8/10引け後に発表した通期上方修正(売上480億円→810億円、営業利益35億円→100億円、中間配当12円増額の24円)を受け、8/12は買い気配のまま一度も寄らずに大引け比例配分でストップ高2,948円となった。汎用DRAM・NANDの需給逼迫と価格上昇を背景に、確保済み在庫の販売で4-6月期営業利益が前年同期比35倍の47.7億円という中身自体は強い。ただし本日成立したのは34,100株・売買代金1.01億円のみで、実質的に売買が成立していない。夜間PTSは3,448円(+16.96%)とさらに上を見ているが、8/13も特別気配が続けば同じことが繰り返される。材料の強さと売買のしやすさは別物であり、寄りで値がつくかどうかが読めない以上、デイトレのプランとしては見送りが基本と考えている。SNSでは4,000円超を期待する値幅取り狙いの投稿が目立つが、こうした断定的な投稿は思惑・煽りを含みうる点にも留意したい。【8/13 7:00 朝更新】8/12夜〜8/13朝にかけて新規のIR・ニュースはなく、材料は8/10引け後の上方修正のままで変わっていない。夜間PTSも3,448円(+16.96%)で夕方から動いておらず、PTS出来高は5,100株と極めて薄い。上昇幅がちょうど+500円で止まっている点はPTSの値幅制限に当たっている可能性があり、この気配から実勢を読むことはできない。米CPI通過で地合いが強含むぶん、8/13も買い気配のまま値がつかない展開になる可能性はむしろ高まったとみて、スコアは24のまま据え置いた。",
