          "stance": "通期経常を44%上方修正・26期ぶり上期最高益。当日-3.22%と決算前に売られた反動も乗る",
          "confidence": "高",
          "confidenceScore": 72,
          "basis": "決算(通期経常84億円→121億円へ44.0%上方修正、上期も39.5億円→55.5億円へ40.5%増額、1Q経常2.4倍の28.2億円、4-6月期の売上営業利益率21.2%→31.6%) × PTS 24,000円(+13.91%、17:48時点、始値23,300円・出来高3,200株・売買代金75百万円) × 当日売買代金71.4億円で流動性ルールを満たす × 8/10の主役が売買代金6,596億円のフジクラ(+7.62%)という光コンポーネント本命だったこととテーマが完全に一致 × 当日は決算前に-3.22%と売られており材料が株価に入っていない",
          "scenario": "8/10の16:00に1Q決算と業績予想の修正を開示した。27年3月期1Qの連結経常利益は前年同期比2.4倍の28.2億円、4-6月期の売上営業利益率が21.2%から31.6%へ大きく上昇している。通期経常は84億円→121億円(前期81.3億円)への44.0%上方修正で増益率が3.2%増から48.7%増に拡大し、上期も39.5億円→55.5億円へ40.5%増額して26期ぶりの上期最高益予想となった。会社側は光コネクタの研磨機・測定装置について顧客の設備投資需要拡大で受注増ペースが加速し、生産キャパの拡大により売上が当初予想を上回ると説明している。当日の株価は決算発表前に21,070円(-3.22%)と売られて引けており、材料は株価に織り込まれていない。夜間PTSは24,000円(+13.91%)。8/10の東京市場ではフジクラが売買代金6,596億円で断トツの主役、内外テック(半導体製造装置商社)がストップ高比例配分と、AI・データセンター向け光通信／半導体装置の資金の向きが明確に出ている点も追い風になる。【8/12朝更新】8/10夜PTSの最終値は23,800円(+12.96%、23:57時点)で、高値は18:04の24,200円、出来高7,100株・売買代金1億6,833万円と、17:48時点で把握していた3,200株から倍増している。気配の信頼度は当初より上がった。休場中の外部環境は米主要3指数が2日続落した一方、8/11のSOXが+0.87%と逆行高し、引け後にスーパー・マイクロが通期売上78%増・営業益2.2倍の好決算を出してAIサーバー需要の強さが再確認された。ドル円も159円28銭と円安方向で、CME先物は大阪日中終値比-75円の横ばい圏。テーマの前提は8/10夕方時点より若干強まったと考えている。8/11に新規の適時開示・レーティング変更はない(同社はアナリストカバレッジなし)。",
          "entry": "PTS水準どおりなら+13%前後のギャップアップになるため寄り成りで飛びつく形は取りにくい。寄り付き後に一度売りをこなして寄り値を維持できるか、フジクラなど同テーマの主力が同時に買われているかを確認してからが目安。8/11の休場を挟むぶん寄り値がPTSより低くなる可能性もあり、その場合はむしろ入りやすくなる。",
          "invalidation": "寄り値を明確に割り込んで前日終値21,070円方向へ戻し始めた場合は、上方修正が2日の間に消化済みと判断された形としてシナリオは無効。フジクラなど光コンポーネント主力が同時に売られる展開になった場合も前提が崩れる。",
          "risk": "8/12は日本時間21:30に米7月CPIの発表が控えており、東京時間は結果待ちで上値が重くなりやすい。8/10に+2.08%と急騰した直後のため指数そのものに利益確定が出る可能性もある。PTSの出来高は夜間セッション通算でも7,100株と薄く(8/12朝時点)、+13%前後という水準が2営業日後の寄り値を正確に示すとは限らない。株価が2万円台と値がさで1単元あたりの必要資金が大きく、値動きも荒くなりやすい。上方修正の要因が顧客の設備投資という外部要因である以上、米国のデータセンター投資に関するネガティブな報道が休場中に出れば前提そのものが弱まる。",
