          "scenario": "8/7の15:30に1Q決算と通期予想の修正を開示した。4-6月期の連結最終利益は前年同期比67.5%増の2,026億円、売上営業利益率が17.5%から24.4%へ大幅に上昇している。通期は売上高4兆300億円→4兆2,300億円(前期比14.4%増)、最終利益6,230億円→7,550億円(同51.9%増)への引き上げで、HRテクノロジー事業の米国中心の好調と、想定為替を1ドル154円→159円へ円安方向に見直したことが要因とされる。当日終値は13,165円(+2.49%)で材料はほぼ株価に入っておらず、夜間PTSは15,200円(+15.46%)。時価総額19.4兆円の超大型株がPTSで15%動くのは異例で、売買代金512.5億円という板の厚さと合わせて、寄り付きで値がつかないリスクが最も小さい銘柄でもある。",
          "entry": "PTS水準どおりなら+15%前後のギャップアップになるため寄り成りで飛びつく形は取りにくい。寄り付き後に売りを一度こなして寄り値を維持できるか、日経平均の下押しに耐える形を確認してからが目安。大型株なので寄り後の値動きは比較的素直になりやすい。",
