          "scenario": "8/7の15:30にIFRSベースの1Q決算と通期予想の修正を開示した。4-6月期の連結最終利益は前年同期比68.3%増の704億円で、売上営業利益率が21.5%から28.7%へ大幅に上昇している。通期最終利益は1,653億円→1,931億円(前期1,359億円)への16.8%上方修正で、増益率が21.6%増から42.1%増に拡大する。当日終値は2,373.0円(+2.64%)と決算期待でやや買われていたが、PTSは2,470円(+4.09%)にとどまり、リクルートHDのような大幅ギャップアップにはなっていない。ギャップが小さいぶん寄り付き後に評価が進む余地が残る形で、8/6以降続く「好業績バリュー・内需の見直し」という物色の方向とも整合する。医療機器というディフェンシブセクターであるため、米雇用統計後にハイテクが売られる展開になっても相対的に資金が残りやすい。",
