          "scenario": "8/6引け後の1Q連結経常利益は前年同期比2.2倍の2,061億円で、通期計画4,300億円に対する進捗率は47.9%と5年平均の26.5%を大きく上回った。Switch 2本体の台数は伸び悩んだ一方でソフト販売が好調に推移し、売上営業利益率が9.9%から27.5%へ改善している点が中身。【朝更新】米国のADR(NTDOY)は8/6終値12.90ドル(+9.60%・出来高111万株)、原株OTCのNTDOFも+9.47%と、東京の当日終値+2.87%に対して海外勢がさらに上乗せして買った形になっている。夜間PTSも8,100円(+6.01%)と夕方時点の+3.5%から上昇しており、複数の市場で同じ方向が確認できた点が朝時点でスコアを引き上げた理由。ただし増益の中身には米IEEPAに基づく関税の還付(約3億ドル)が含まれ、Switch 2ハードは382万台(前年同期比-34.4%)である点は割り引いて見る必要がある。",
          "entry": "ADR基準では+9%前後、PTS基準では+6%前後のギャップアップが前提で、寄り成りで飛びつく形は取りにくい。寄り付き後に一度売りをこなして寄り値を維持できるか、日経平均の下押しに耐える形を確認してからが目安。",
