      "summary": "8/5(水)の東京市場は全面高。日経平均は前日比2,342円91銭高(+3.66%)の6万6,300円44銭と大幅続伸し、節目の6万6,000円台を回復して7/23以来約2週間ぶりの高値を付けた。前日の米国市場でダウ(+1.71%)とS&P500(+1.79%)がそろって最高値を更新し、SOX指数が+6.55%と急騰したことで半導体・AI関連に買いが集中、アドバンテスト1銘柄で日経平均を約504円押し上げた。TOPIXは4,046.17(+84.39/+2.13%)、東証グロース市場250指数は723.41(+19.59/+2.78%)とそろって続伸。プライムの売買代金は約10兆9,200億円で、値上がり1,019・値下がり491・変わらず48と全体の約3分の2が上昇する全面高商状だった。業種別では非鉄金属+9.08%を筆頭にガラス土石+4.64%・情報通信+4.60%・電気機器+4.16%が買われた一方、ホルムズ海峡開放を巡る米イラン合意期待で原油が急落したため海運-2.93%・鉱業-2.15%・倉庫運輸-1.97%は逆行安となり、資源・海運だけが取り残された。個別ではイビデンが上方修正と株式分割でストップ高、ヤマハ発動機が+19.46%と急騰する一方、決算を嫌気した横河電機-10.04%・三井倉庫HD-11.10%が下落率上位に並んだ。",
